function header(){return '<header class="topbar"><div class="topline"><div><div class="brand">NFL SPREAD TOOL</div><div class="brand-sub">Category · tier · market · evidence</div></div>'+weekControl()+'</div></header>'}
function nav(){return '<nav class="bottom-nav">'+[['dashboard','⌂','Dashboard'],['games','▦','Games'],['picks','✓','Picks'],['tools','⚙','Tools']].map(function(x){return '<button class="nav '+(S.tab===x[0]?'active':'')+'" data-tab="'+x[0]+'"><span class="nav-icon">'+x[1]+'</span><span class="nav-label">'+x[2]+'</span></button>'}).join('')+'</nav>'}
function status(){var f=S.fresh||{},state=f.overallState||f.state||'CURRENT',r=S.dashboard&&S.dashboard.results,p=S.dashboard&&S.dashboard.seasonPulse,n=p&&p.gamesConsidered;return '<div class="status"><div class="status-top"><span>DATA STATUS</span><span class="status-state">'+e(state)+'</span></div><div class="status-sub">'+e(r?r.completedGames+' completed · '+r.awaitingCompletion+' awaiting completion':'Schedule loaded')+(n!=null?' · Season tiers through '+e(n)+' completed games':'')+'</div></div>'}
function gameState(g){if(g.final)return 'FINAL';if(g.live)return 'LIVE';return 'UPCOMING'}
function spreadOf(g){return g.spread||{away:g.medianAwaySpread,home:g.medianHomeSpread,projectedTeam:g.projectedTeam,coverRate:g.projectedCoverRate,grade:g.grade,sampleSize:g.sampleSize,status:g.projectionStatus}}
function marketOf(g){var m=g.market||g.moneyline||{};return {awayMoneyline:m.awayMoneyline!=null?m.awayMoneyline:m.consensusAwayMoneyline,homeMoneyline:m.homeMoneyline!=null?m.homeMoneyline:m.consensusHomeMoneyline,awayWinPct:m.awayWinPct!=null?m.awayWinPct:m.awayWinProbability,homeWinPct:m.homeWinPct!=null?m.homeWinPct:m.homeWinProbability,books:m.books||[]}}
function mergedGames(){var dash=S.dashboard&&S.dashboard.games||[],pool=S.pool&&S.pool.games||[],focus=S.focus&&S.focus.games||[],pBy={},fBy={};pool.forEach(function(g){pBy[String(g.gameId)]=g});focus.forEach(function(g){fBy[String(g.gameId)]=g});return dash.map(function(g){var p=pBy[String(g.id)]||{},s=p.spread||spreadOf(g);return Object.assign({},g,p,{id:g.id,spread:s,market:p.market||marketOf(g),movement:p.movement||null,history:p.history||null,context:p.context||null,outlook:p.outlook||null,brain:fBy[String(g.id)]||null,classification:g.classification||p.classification||null,projectedTeam:g.projectedTeam||s.projectedTeam,projectedCoverRate:g.projectedCoverRate!=null?g.projectedCoverRate:s.coverRate,sampleSize:g.sampleSize!=null?g.sampleSize:s.sampleSize,grade:g.grade||s.grade,projectionStatus:g.projectionStatus||s.status,final:g.final||p.final,postgame:g.postgame||null})})}
function classificationFor(g,side){return g.classification&&g.classification[side]}
function projectedClass(g){if(g.projectedClassification)return g.projectedClassification;var side=g.projectedTeam===g.awayTeam?'away':g.projectedTeam===g.homeTeam?'home':null;return side?classificationFor(g,side):null}
function record(b){if(!b)return 'n=0';return Number(b.wins||0)+'-'+Number(b.losses||0)+(Number(b.pushes||0)?'-'+Number(b.pushes||0):'')}
function projectedBucket(g){var side=g.projectedTeam===g.awayTeam?'away':g.projectedTeam===g.homeTeam?'home':null;return side&&g.currentSeasonStats?g.currentSeasonStats[side]:null}
