function trend(b){var m=b&&b.momentum||[],last=m[m.length-1];if(!last)return '';var previous=m.length>1?m[m.length-2].cumulative.coverRate:null,current=last.cumulative.coverRate,delta=num(previous)===null||num(current)===null?null:Math.round((current-previous)*10)/10,arrow=delta===null?'':delta>0?'↑':delta<0?'↓':'→';return '<span class="pulse-trend '+(delta<0?'down':'')+'">W'+e(last.week)+' '+e(pct(last.weekly.coverRate))+(arrow?' · '+arrow+Math.abs(delta)+' pts':'')+'</span>'}
function pulse(){var rows=[['Away Dog','AwayDog'],['Away Favorite','AwayFav'],['Home Dog','HomeDog'],['Home Favorite','HomeFav']],ts=[['0.5–3','<=3'],['3.5–7','<=7'],['7.5+','>7']],sp=S.dashboard&&S.dashboard.seasonPulse;return '<section class="section"><div class="section-head"><div class="section-title">Tier Pulse</div><div class="section-meta">'+e(S.season||'Current')+' season'+(sp&&sp.throughWeek?' · through W'+e(sp.throughWeek):'')+' · tap for games</div></div><div class="pulse"><div class="pulse-row"><div></div>'+ts.map(function(t){return '<div class="pulse-head">'+t[0]+'</div>'}).join('')+'</div>'+rows.map(function(r){return '<div class="pulse-row"><div class="pulse-label">'+r[0]+'</div>'+ts.map(function(t){var b=bucket(r[1],t[1]),hot=b&&Number(b.rate)>=55;return '<button class="pulse-cell '+(hot?'hot':'')+'" data-bucket="'+r[1]+'|'+t[1]+'"><strong>'+(b&&b.rate!=null?e(b.rate)+'%':'—')+'</strong><span>'+(b?e(b.record):'n=0')+' season</span>'+trend(b)+'</button>'}).join('')+'</div>'}).join('')+'</div></section>'}
function strategy(g){var b=g.brain||{},x=String(b.bestUse||'');if(x.indexOf('SPREAD +')>=0)return 'Spread + outright';if(x.indexOf('SPREAD')>=0)return 'Spread';if(x.indexOf('POOL')>=0||x.indexOf('OUTRIGHT')>=0||x.indexOf('SURVIVOR')>=0)return 'Outright pool';if(x.indexOf('WATCH')>=0)return 'Watch';return g.grade?'Spread':'Pass'}
function brainText(g){var b=g.brain;if(!b)return 'Tier signal available; supporting evidence not loaded.';var supports=Number(b.independentSignals||0),conflicts=(b.conflict||[]).length;return supports+' independent signal'+(supports===1?'':'s')+' support'+(supports===1?'s':'')+(conflicts?' · '+conflicts+' conflict'+(conflicts===1?'':'s'):' · no primary conflict')}
function contextText(g){var obs=g.context&&g.context.observations||[];if(!obs.length)return '';var x=obs.find(function(o){return o.kind==='supporting'||o.kind==='interesting'})||obs[0];return x.label+': '+x.detail}
function movementText(g){var m=g.movement;if(!m||num(m.firstCapturedAwaySpread)===null)return 'Line history unavailable';var final=gameState(g)==='FINAL',end=final&&num(m.closingAwaySpread)!==null?m.closingAwaySpread:m.currentAwaySpread,label=final?'Close':'Current';if(num(end)===null)return 'Open '+code(g.awayTeam)+' '+signed(m.firstCapturedAwaySpread)+' · current unavailable';return 'Open '+code(g.awayTeam)+' '+signed(m.firstCapturedAwaySpread)+' → '+label+' '+code(g.awayTeam)+' '+signed(end)}
function movementDelta(g){var m=g.movement,mag=m&&num(m.movementMagnitude);if(mag===null)return '';if(mag===0)return 'No movement';var toward=m.direction==='TOWARD_AWAY'?code(g.awayTeam):m.direction==='TOWARD_HOME'?code(g.homeTeam):'';return mag+' pt'+(mag===1?'':'s')+(toward?' toward '+toward:'')}
function moneylineMovementText(g){var m=g.movement&&g.movement.moneyline;if(!m||num(m.openingAwayMoneyline)===null)return 'Moneyline history unavailable';var final=gameState(g)==='FINAL',a=final&&num(m.closingAwayMoneyline)!==null?m.closingAwayMoneyline:m.currentAwayMoneyline,h=final&&num(m.closingHomeMoneyline)!==null?m.closingHomeMoneyline:m.currentHomeMoneyline,label=final?'Close':'Current';if(num(a)===null||num(h)===null)return 'ML Open '+code(g.awayTeam)+' '+ml(m.openingAwayMoneyline)+' / '+code(g.homeTeam)+' '+ml(m.openingHomeMoneyline)+' · current unavailable';return 'ML Open '+code(g.awayTeam)+' '+ml(m.openingAwayMoneyline)+' / '+code(g.homeTeam)+' '+ml(m.openingHomeMoneyline)+' → '+label+' '+code(g.awayTeam)+' '+ml(a)+' / '+code(g.homeTeam)+' '+ml(h)}
function moneylineMovementDelta(g){var m=g.movement&&g.movement.moneyline,mag=m&&num(m.probabilityMagnitude);if(mag===null)return '';var total=num(m.bookmakerCount)||0;if(m.direction==='UNCHANGED')return 'No ML movement'+(total?' · '+total+' books':'');var away=m.direction==='TOWARD_AWAY',toward=away?code(g.awayTeam):m.direction==='TOWARD_HOME'?code(g.homeTeam):'',moved=away?num(m.towardAwayBookmakers):num(m.towardHomeBookmakers);return (toward?toward+' +':'')+mag+' probability pt'+(mag===1?'':'s')+(total?' · '+(moved||0)+'/'+total+' books':'')}
function marketRead(g){var a=g.movement&&g.movement.marketAlignment,sm=g.movement,mm=sm&&sm.moneyline,spreadTeam=sm&&sm.direction==='TOWARD_AWAY'?code(g.awayTeam):sm&&sm.direction==='TOWARD_HOME'?code(g.homeTeam):'',mlTeam=mm&&mm.direction==='TOWARD_AWAY'?code(g.awayTeam):mm&&mm.direction==='TOWARD_HOME'?code(g.homeTeam):'';if(a==='ALIGNED')return {key:a,label:'Aligned',text:'Spread and moneyline both strengthened toward '+spreadTeam};if(a==='DIVERGENT')return {key:a,label:'Divergent',text:'Spread moved toward '+spreadTeam+' while moneyline moved toward '+mlTeam};if(a==='SPREAD_ONLY')return {key:a,label:'Spread only',text:'Spread moved, while the moneyline stayed stable'};if(a==='MONEYLINE_ONLY')return {key:a,label:'Moneyline only',text:'Moneyline moved, while the spread stayed stable'};if(a==='STABLE')return {key:a,label:'Stable',text:'No meaningful spread or moneyline movement'};return {key:'INCOMPLETE',label:'Incomplete',text:'Both spread and moneyline history are needed for a market read'}}
function compactMoneylineMovement(g){var m=g.movement&&g.movement.moneyline;if(!m||num(m.openingAwayMoneyline)===null)return '';var final=gameState(g)==='FINAL',end=final&&num(m.closingAwayMoneyline)!==null?m.closingAwayMoneyline:m.currentAwayMoneyline,label=final?'Close':'Current';return 'ML Open '+code(g.awayTeam)+' '+ml(m.openingAwayMoneyline)+' → '+label+' '+ml(end)}
function focusGames(){var order={A:3,B:2,C:1};return mergedGames().filter(function(g){return !g.final&&['A','B','C'].indexOf(g.grade)>=0&&num(g.projectedCoverRate)>=55}).sort(function(a,b){return order[b.grade]-order[a.grade]||num(b.projectedCoverRate)-num(a.projectedCoverRate)||String(a.kickoffAt).localeCompare(String(b.kickoffAt))})}
function focus(){var list=focusGames();return '<section class="section"><div class="section-head"><div><div class="section-title">Qualified Games This Week</div><div class="focus-evidence">Upcoming games in categories currently hitting 55%+</div></div><div class="section-meta">'+list.length+' game'+(list.length===1?'':'s')+'</div></div>'+(list.length?'<div class="focus-list">'+list.map(function(g){var s=spreadOf(g),m=marketOf(g),b=projectedBucket(g),isAway=g.projectedTeam===g.awayTeam,line=isAway?s.away:s.home,price=isAway?m.awayMoneyline:m.homeMoneyline;return '<button class="focus-row" data-game="'+e(g.id)+'"><span class="grade '+String(g.grade).toLowerCase()+'">'+e(g.grade)+'</span><span><div class="focus-match">'+e(code(g.awayTeam))+' @ '+e(code(g.homeTeam))+' · '+e(code(g.projectedTeam))+' '+e(signed(line))+'</div><div class="focus-category">'+e(cls(projectedClass(g)))+' · '+e(tier(g.classification&&g.classification.tier))+'</div><div class="focus-market">ML '+e(ml(price))+' · '+e(movementText(g))+'</div><div class="focus-evidence">Strategy: '+e(strategy(g))+' · '+e(brainText(g))+(contextText(g)?' · '+e(contextText(g)):'')+'</div></span><span class="focus-rate">'+e(pct(g.projectedCoverRate))+'<span>'+e(record(b))+' · n='+e(g.sampleSize||0)+'</span></span></button>'}).join('')+'</div>':'<div class="empty">No upcoming Week '+e(S.week)+' games belong to a category currently hitting 55% or better. Games without a posted line remain unclassified.</div>')+'</section>'}
