function filterGames(games){if(S.bucketFilter){var p=S.bucketFilter.split('|'),name=p[0],t=p[1];return games.filter(function(g){return g.classification&&g.classification.tier===t&&(g.classification.away===name||g.classification.home===name)})}if(S.filter==='FOCUS')return games.filter(function(g){return ['A','B','C'].indexOf(g.grade)>=0});if(S.filter!=='ALL')return games.filter(function(g){return g.grade===S.filter});return games}
