function teamBlock(g,away,a,h){var s=spreadOf(g),m=marketOf(g),team=away?g.awayTeam:g.homeTeam,spread=away?s.away:s.home,price=away?m.awayMoneyline:m.homeMoneyline,score=away?a:h,other=away?h:a;return '<div class="team '+(away?'':'home')+'">'+(away?'<img class="logo" alt="" src="'+e(logo(team))+'">':'')+'<div><div class="team-code">'+e(code(team))+'</div><div class="team-name">'+e(team)+'</div><div class="team-market">'+e(signed(spread))+' <span class="money">· ML '+e(ml(price))+'</span></div>'+(score!=null?'<div class="score '+(Number(score)<Number(other)?'loser':'')+'">'+e(score)+'</div>':'')+'</div>'+(!away?'<img class="logo" alt="" src="'+e(logo(team))+'">':'')+'</div>'}
