function bucketView(){var games=filterGames(mergedGames()).filter(function(g){return gameState(g)!=='FINAL'}),c=S.contributors,p=S.bucketFilter&&S.bucketFilter.split('|'),b=p&&bucket(p[0],p[1]),summary=c?(c.wins+'-'+c.losses+(c.pushes?' ('+c.pushes+' push)':'')+' · '+pct(c.coverRate)+' · n='+c.decisions):(b?b.record+' · '+b.rate+'%':'Loading contributors…');return '<div class="bucket-banner"><div><strong>'+e(bucketLabel())+' · Season to date</strong><span>'+e(summary)+'</span></div><button data-clear-bucket>Clear ×</button></div><div class="bucket-section"><div class="bucket-title">Weekly Momentum</div>'+(c?momentumRows(c):'<div class="empty">Loading season momentum…</div>')+'</div><div class="bucket-section"><div class="bucket-title">All Season Contributors · '+e(c?c.games.length:'…')+'</div>'+(c?(c.games.length?'<div class="contributors">'+c.games.map(contributorCard).join('')+'</div>':'<div class="empty">No completed games have contributed to this bucket yet.</div>'):'<div class="empty">Loading every current-season contributor…</div>')+'</div><div class="bucket-section"><div class="bucket-title">Week '+e(S.week)+' Matches · '+games.length+'</div><div class="games">'+(games.length?games.map(gameCard).join(''):'<div class="empty">No upcoming Week '+e(S.week)+' games currently belong to this category and tier.</div>')+'</div></div>'}
